insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('property-media','property-media',false,10485760,array['image/webp'])on conflict(id)do nothing;
create policy rivton_media_insert on storage.objects for insert to authenticated with check(bucket_id='property-media' and (storage.foldername(name))[1]=(select auth.uid())::text and (select rivton_private.member_role()) in ('owner','editor','agent') and name~'^[a-f0-9-]{36}/[a-f0-9]{64}\.webp$');
create policy rivton_media_read on storage.objects for select to anon,authenticated using(bucket_id='property-media' and rivton_private.media_visible(name));
-- No UPDATE/DELETE policy: shared or published assets cannot be overwritten/deleted from a browser.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('media-originals','media-originals',false,10485760,array['image/jpeg','image/png','image/webp','image/avif'])on conflict(id)do nothing;
create policy rivton_original_insert on storage.objects for insert to authenticated with check(bucket_id='media-originals' and (storage.foldername(name))[1]=(select auth.uid())::text and (select rivton_private.member_role())in('owner','editor','agent') and name~'^[a-f0-9-]{36}/[a-f0-9-]{36}$' and rivton_private.upload_allowed(name));
create policy rivton_original_read on storage.objects for select to authenticated using(bucket_id='media-originals' and (storage.foldername(name))[1]=(select auth.uid())::text and (select rivton_private.member_role())in('owner','editor','agent'));
create policy rivton_original_delete on storage.objects for delete to authenticated using(bucket_id='media-originals' and (storage.foldername(name))[1]=(select auth.uid())::text and (select rivton_private.member_role())in('owner','editor','agent'));
